def test_content_notices_are_separate_approved_publication_guidance(self):
    expected = module.CONTENT_NOTICE_POLICY['records']
    self.assertEqual({r['id'] for r in self.records if r['contentNotice']}, set(expected))
    for record in self.records:
        self.assertEqual(record['contentNotice'], [{'type': kind, 'label': module.CONTENT_NOTICE_POLICY['types'][kind]} for kind in expected.get(record['id'], [])])
        for item in record['contentNotice']:
            self.assertNotIn(item['type'], record['issues'])
    self.assertEqual(len(self.records), 500)
